<script setup lang="ts">
import {nodeDisplayName} from '../nodePresentation'
import {computed,onBeforeUnmount,onMounted,ref} from 'vue'
import {api,request} from '../api'
import {useWorkspace} from '../workspace'
import {bytes,date,stateLabel,type MonitorJob,type NodeOption} from '../domain'
import Icon from './Icon.vue'
import Modal from './Modal.vue'
const w=useWorkspace(),busy=ref(''),remove=ref<MonitorJob|null>(null),budget=ref<Record<string,any>|null>(null),storage=ref<Record<string,any>|null>(null),details=ref<MonitorJob|null>(null),runs=ref<Record<string,any>[]>([]);let timer:ReturnType<typeof setInterval>|undefined
const active=computed(()=>w.jobs.value.filter(j=>j.state==='running').length)
async function reload(){await w.refreshJobs();const results=await Promise.allSettled([api.budget(),api.storage()]);if(results[0].status==='fulfilled')budget.value=results[0].value;if(results[1].status==='fulfilled')storage.value=results[1].value}
async function action(job:MonitorJob,type:string,body?:unknown){busy.value=job.id;try{await api.jobAction(job.id,type,body);await reload();w.notify(type==='trigger'?'已请求执行一次检测':'任务已更新')}catch(e){w.fail(e)}finally{busy.value=''}}
async function deleteJob(){if(!remove.value)return;busy.value=remove.value.id;try{await api.deleteJob(remove.value.id);remove.value=null;await reload();w.notify('任务已删除，原始历史保留')}catch(e){w.fail(e)}finally{busy.value=''}}
const runsLoading=ref(false),runsError=ref('');let runsGeneration=0
function closeRuns(){runsGeneration++;details.value=null;runs.value=[];runsLoading.value=false;runsError.value=''}
async function show(job:MonitorJob){const token=++runsGeneration;details.value=job;runs.value=[];runsLoading.value=true;runsError.value='';try{const result=await request<Record<string,any>[]>(`/api/monitor/runs?job_id=${encodeURIComponent(job.id)}&limit=20`,'GET',undefined,'QueryMonitorRuns',[job.id,20]);if(token===runsGeneration)runs.value=result||[]}catch(e){if(token===runsGeneration)runsError.value=e instanceof Error?e.message:String(e)}finally{if(token===runsGeneration)runsLoading.value=false}}
function nodeOption(job:MonitorJob,n:NodeOption):NodeOption{return {...n,profile_id:job.profile_id,profile_name:job.profile_name,country_code:'',country_flag:''}}
onMounted(()=>{void reload().catch(w.fail);timer=setInterval(()=>{if(w.page.value==='monitor'&&document.visibilityState==='visible')void reload().catch(w.fail)},15000)});onBeforeUnmount(()=>{clearInterval(timer);runsGeneration++})
</script>
<template><section class="page-view"><div class="page-header"><div><h1>持续监测</h1><p>{{active}} 个任务运行中 · {{w.jobs.value.length}} 个任务</p></div><div class="button-group"><button class="button ghost" @click="reload().catch(w.fail)"><Icon name="refresh"/>刷新</button><button class="button primary" @click="w.page.value='home';w.multiSelect.value=true"><Icon name="plus"/>选节点创建</button></div></div><div v-if="budget||storage" class="monitor-resource"><span v-if="budget">今日请求 {{budget.usage?.requests_used||0}} · 已读取 {{bytes(budget.usage?.bytes_used)}}</span><span v-if="storage">历史占用 {{bytes(storage.total_bytes)}}</span><button class="text-button" @click="w.page.value='settings'">调整监测与保存策略</button></div><p v-if="budget?.blocked_reason||storage?.protected" class="inline-warning">{{budget?.blocked_reason||'历史容量达到保护阈值，新的监测采样已受限。'}}</p><div class="monitor-cards"><article v-for="job in w.jobs.value" :key="job.id" class="monitor-card"><header><div><h2>{{job.name}}</h2><small>{{job.profile_name}}</small></div><span class="badge" :class="job.state==='running'?'good':job.state==='blocked'?'warn':''">{{job.state==='running'?'监测中':stateLabel(job.state)}}</span></header><div class="monitor-spec"><span>{{job.node_keys?.length||0}} 个节点</span><span>每 {{job.interval_seconds>=60?`${job.interval_seconds/60} 分钟`:`${job.interval_seconds} 秒`}}</span><span>{{job.probe_set==='light'?'延迟与连接':job.probe_set==='service'?'基础服务':'深度诊断'}}</span><span>{{job.sampling_tier==='focus'?'重点':job.sampling_tier==='sparse'?'稀疏':'常规'}}采样</span></div><p v-if="job.blocked_reason||job.recovery_reason||job.persistence_error||job.storage_reason||job.budget_reason" class="inline-warning">{{job.blocked_reason||job.persistence_error||job.storage_reason||job.budget_reason||job.recovery_reason}}</p><details class="monitor-nodes"><summary>查看 {{job.nodes?.length||0}} 个节点</summary><button v-for="n in job.nodes" :key="n.node_key" class="compact-row text-button" @click="w.inspectNode.value=nodeOption(job,n)">{{nodeDisplayName(n)}}<Icon name="chevron"/></button></details><footer><div class="button-group"><button v-if="job.state==='running'" class="button" :disabled="busy===job.id" @click="action(job,'pause')"><Icon name="pause"/>暂停</button><button v-else class="button primary" :disabled="busy===job.id||job.state==='blocked'" @click="action(job,job.state==='paused'?'resume':'start')"><Icon name="play"/>{{job.state==='paused'?'继续':'启动'}}</button><button v-if="job.state==='running'||job.state==='paused'" class="button ghost" :disabled="busy===job.id" @click="action(job,'stop')">停止</button><button class="button ghost" :disabled="busy===job.id||!['running','paused'].includes(job.state)" @click="action(job,'trigger')">检测一次</button><button class="button ghost" @click="show(job)">运行记录</button><button class="button ghost icon-button" aria-label="删除监测任务" @click="remove=job"><Icon name="trash"/></button></div><label class="check-field small"><input type="checkbox" :checked="job.resume_on_launch" :disabled="busy===job.id" @change="action(job,'resume-on-launch',{enabled:($event.target as HTMLInputElement).checked})">启动应用时继续</label></footer></article></div><div v-if="!w.jobs.value.length" class="empty-state"><Icon name="monitor"/><h3>让常用节点持续留下记录</h3><p>在首页多选节点，再点“加入持续监测”。跨订阅选择会自动拆成任务。</p><button class="button primary" @click="w.page.value='home';w.multiSelect.value=true">选择节点</button></div><Modal v-if="remove" title="删除监测任务" @close="remove=null"><p>删除「{{remove.name}}」并停止后续监测，已经保存的原始记录保留。</p><template #footer><button class="button" @click="remove=null">返回</button><button class="button danger-fill" :disabled="!!busy" @click="deleteJob">删除任务</button></template></Modal><Modal v-if="details" :title="details.name+' · 运行记录'" wide @close="closeRuns"><div class="table-scroll"><table><thead><tr><th>时间</th><th>状态</th><th>成功节点</th><th>失败节点</th></tr></thead><tbody><tr v-for="run in runs" :key="run.run_id"><td>{{date(run.started_at)}}</td><td>{{stateLabel(run.status)}}<small v-if="run.error_message">{{run.error_message}}</small></td><td>{{run.success_nodes}} / {{run.total_nodes}}</td><td>{{run.failed_nodes}}</td></tr></tbody></table></div><p v-if="runsLoading" class="muted">读取运行记录中…</p><p v-else-if="runsError" class="inline-error" role="alert">运行记录读取失败：{{runsError}} <button class="text-button" @click="show(details!)">重新读取</button></p><p v-else-if="!runs.length" class="muted">还没有运行记录。</p></Modal></section></template>
